/* From Uiverse.io by Yaseen549 - Tags: input */
.__UIV_SCOPE__ .input {
 border: 2px solid #e8e8e8;
 padding: 15px;
 border-radius: 10px;
 background-color: #212121;
 font-size: small;
 font-weight: bold;
 text-align: center;
}

.__UIV_SCOPE__ .input:focus {
 outline-color: white;
 background-color: #212121;
 color: #e8e8e8;
 box-shadow: 5px 5px #888888;
}
